import{_ as s,o as e,c as a,ae as n}from"./chunks/framework.Co1PSFSm.js";const c=JSON.parse('{"title":"","description":"使用 deno compile 生成自包含可执行文件。","frontmatter":{"description":"使用 deno compile 生成自包含可执行文件。"},"headers":[],"relativePath":"zh/deployment/deno-compile.md","filePath":"zh/deployment/deno-compile.md"}'),t={name:"zh/deployment/deno-compile.md"};function l(p,i,h,o,d,r){return e(),a("div",null,[...i[0]||(i[0]=[n(`<p>你可以使用 <a href="https://docs.deno.com/runtime/reference/cli/compile/" target="_blank" rel="noreferrer"><code>deno compile</code> 命令</a> 将应用创建为自包含的可执行文件。它会包含所有资源和依赖项。这个可执行文件可以在任何平台上运行，无需安装 Deno。</p><h2 id="构建可执行文件" tabindex="-1">构建可执行文件 <a class="header-anchor" href="#构建可执行文件" aria-label="Permalink to &quot;构建可执行文件&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 首先构建你的应用</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> task</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生成自包含可执行文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _fresh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _fresh/compiled-entry.js</span></span></code></pre></div><p><code>--include _fresh</code> 标志确保所有构建后的资源（JavaScript 打包文件、CSS、静态文件）都嵌入到二进制文件中。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>编译后的入口支持两个开箱即用的环境变量：</p><ul><li><code>PORT</code> 用于设置端口号（<code>PORT=4000 ./my-app</code>）</li><li><code>HOSTNAME</code> 用于设置主机名（<code>HOSTNAME=0.0.0.0 ./my-app</code>）</li></ul><h2 id="交叉编译" tabindex="-1">交叉编译 <a class="header-anchor" href="#交叉编译" aria-label="Permalink to &quot;交叉编译&quot;">​</a></h2><p>你可以使用 <code>--target</code> 标志为不同的平台进行编译：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x86_64-unknown-linux-gnu</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _fresh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _fresh/compiled-entry.js</span></span></code></pre></div><p>请参阅 <a href="https://docs.deno.com/runtime/reference/cli/compile/" target="_blank" rel="noreferrer"><code>deno compile</code> 文档</a> 获取支持的目标完整列表。</p><h2 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h2><ul><li>可执行文件大小包含 Deno 运行时（约 50-130 MB，取决于平台）</li><li>无法静态分析的动态导入可能不会被包含</li><li>具有平台特定二进制文件的原生 npm 包需要与目标平台匹配</li></ul>`,13)])])}const F=s(t,[["render",l]]);export{c as __pageData,F as default};
